/**
 * Renders the Cordis patch that declares the Arena route natively.
 *
 * The generated file is the whole point of this variant: DeepSeek Harness' own
 * `@deepseek-ai/dsh-llm-pi-ai` adapter talks to Arena directly (no local proxy),
 * and this patch is the single, readable place where the route and its models
 * live. Regenerating it after `--sync` replaces the model list wholesale.
 */
import { DEFAULT_API_BASE } from './catalog.js'

export const ROUTE_PATCH_HEADER = [
  '# Generated by dsh-freemodels-arena-native — do not edit the model list by hand.',
  '#',
  '# Regenerate with:  node bin/arena-setup.mjs --sync',
  '# Plugin id, route key and the credential reference are stable; only the',
  "# models list follows Arena's live catalog.",
].join('\n')

/** YAML plain scalars are safe for these; everything else gets JSON quoting. */
const PLAIN_SCALAR = /^[A-Za-z_][A-Za-z0-9_.-]*$/

export function scalar(value) {
  const text = String(value)
  return PLAIN_SCALAR.test(text) ? text : JSON.stringify(text)
}

/**
 * @param {object} options
 * @param {{id: string, name?: string, contextWindow?: number, maxTokens?: number, input?: string[]}[]} options.models
 * @param {string} [options.baseURL] Arena base URL written into the route.
 * @param {string} [options.displayName] Route label for the model picker.
 * @param {string} [options.apiKeyEnv] Credential reference (default ARENA_API_KEY).
 * @param {string} [options.route] Route key / provider name (default arena).
 * @param {string} [options.pluginName] Package name of this plugin.
 * @param {string} [options.generatedAt] ISO timestamp for the header comment.
 * @returns {string} YAML patch text
 *
 * @example
 * renderRoutePatch({ models: [{ id: 'coding-router-preview', contextWindow: 1_000_000 }] })
 */
export function renderRoutePatch({
  models,
  baseURL = DEFAULT_API_BASE,
  displayName = 'Arena',
  apiKeyEnv = 'ARENA_API_KEY',
  route = 'arena',
  pluginName = 'dsh-freemodels-arena-native',
  generatedAt = new Date().toISOString(),
} = {}) {
  if (!Array.isArray(models) || models.length === 0) {
    throw new Error('Refusing to render a route patch without models')
  }
  if (!/^[a-z][a-z0-9-]*$/.test(route)) {
    throw new Error(`Route key "${route}" must be a lowercase identifier (a-z, 0-9, -)`)
  }
  const lines = [
    ROUTE_PATCH_HEADER,
    `# Synced: ${generatedAt}`,
    '- insert:',
    `    - id: ${route}-plugin`,
    `      name: ${pluginName}`,
    '    - id: freemodels-arena-route',
    "      name: '@deepseek-ai/dsh-llm-pi-ai'",
    '      config:',
    '        providers:',
    `          ${route}:`,
    `            displayName: ${scalar(displayName)}`,
    '            api: openai-completions',
    `            baseURL: ${baseURL}`,
    `            apiKeyEnv: ${apiKeyEnv}`,
    '            models:',
  ]

  for (const model of models) {
    const id = typeof model?.id === 'string' ? model.id.trim() : ''
    if (!id) throw new Error('Refusing to render a model without an id')
    lines.push(`              - id: ${scalar(id)}`)
    if (model.name && model.name !== id) lines.push(`                name: ${scalar(model.name)}`)
    if (Number.isFinite(model.contextWindow) && model.contextWindow > 0) {
      lines.push(`                contextWindow: ${Math.trunc(model.contextWindow)}`)
    }
    if (Number.isFinite(model.maxTokens) && model.maxTokens > 0) {
      lines.push(`                maxTokens: ${Math.trunc(model.maxTokens)}`)
    }
    if (Array.isArray(model.input) && model.input.length > 0) {
      lines.push(`                input: [${model.input.join(', ')}]`)
    }
  }
  lines.push('')
  return lines.join('\n')
}

/**
 * Model ids declared by a rendered patch (14-space entries), so `--doctor` and
 * the tests can diff a local patch against Arena's live catalog.
 */
export function patchModelIds(yaml) {
  return [...String(yaml ?? '').matchAll(/^ {14}- id: (.+)$/gm)]
    .map(match => match[1].trim().replace(/^"(.*)"$/, '$1'))
}

/** Route keys declared by a patch — used to refuse duplicate route registration. */
export function patchRouteKeys(yaml) {
  const text = String(yaml ?? '')
  const key = /^ {10}([a-z][a-z0-9-]*):$/m.exec(text)
  return key ? [key[1]] : []
}
